CREATE OR REPLACE FUNCTION hawala.settlement(p jsonb) RETURNS json LANGUAGE plpgsql AS $body$
DECLARE
    tenant bigint:=(p->>'TenantId')::bigint; actor bigint:=(p->>'CurrentUserId')::bigint; owner bigint:=(p->>'CorrespondentId')::bigint;
    mode text:=p->>'SourceMode'; note text:=nullif(btrim(p->>'Note'),''); owner_name text; target bigint; target_code text; target_priority integer; places integer;
    account bigint; clearing bigint; branch bigint; posting bigint; conversion bigint; hawala_count integer; currency_count integer; prefix text; next_number integer;
    now_utc timestamp:=CURRENT_TIMESTAMP AT TIME ZONE 'UTC'; description text; previous_timeout text; result json;
BEGIN
    IF mode IS NULL OR mode NOT IN('Hawalas','Account') OR coalesce(owner,0)<=0 THEN RAISE EXCEPTION 'روش تبدیل یا نمایندگی معتبر نیست.'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public."Users" WHERE "TenantId"=tenant AND "Id"=actor AND "IsActive") THEN RAISE EXCEPTION 'کاربر جاری معتبر نیست.'; END IF;
    previous_timeout:=current_setting('lock_timeout');PERFORM set_config('lock_timeout','30s',true);
    PERFORM pg_advisory_xact_lock(hashtextextended('CorrespondentSettlement:'||tenant||':'||owner,0));
    PERFORM set_config('lock_timeout','5s',true);PERFORM pg_advisory_xact_lock(hashtextextended('CorrespondentCommissionPeriod:'||tenant||':'||owner,0));
    PERFORM set_config('lock_timeout','30s',true);
    SELECT "Name","SettlementCurrencyId" INTO owner_name,target FROM public."Correspondents" WHERE "TenantId"=tenant AND "Id"=owner AND NOT "IsArchived" FOR UPDATE;
    IF NOT FOUND OR target IS NULL THEN RAISE EXCEPTION 'نمایندگی فعال یا ارز توافقی یافت نشد.'; END IF;
    SELECT "Code","QuotationPriority","DecimalPlaces" INTO target_code,target_priority,places FROM public."Currencies" WHERE "TenantId"=tenant AND "Id"=target AND "IsActive";
    IF NOT FOUND THEN RAISE EXCEPTION 'ارز توافقی این نمایندگی غیرفعال یا نامعتبر است.'; END IF;
    SELECT "Id" INTO account FROM public."Accounts" WHERE "TenantId"=tenant AND "CorrespondentId"=owner AND NOT "IsArchived" ORDER BY "Id" LIMIT 1 FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'حساب فعال نمایندگی یافت نشد.'; END IF;
    DROP TABLE IF EXISTS pg_temp."SettlementRates",pg_temp."SelectedHawalas",pg_temp."SettlementBalances";
    CREATE TEMP TABLE "SettlementRates"("HawalaId" bigint,"SourceCurrencyId" bigint,"Rate" numeric(18,8) NOT NULL,PRIMARY KEY("HawalaId","SourceCurrencyId")) ON COMMIT DROP;
    INSERT INTO "SettlementRates" SELECT * FROM jsonb_to_recordset(coalesce(p->'Rates','[]'::jsonb)) AS x("HawalaId" bigint,"SourceCurrencyId" bigint,"Rate" numeric(18,8));
    CREATE TEMP TABLE "SelectedHawalas"("Id" bigint PRIMARY KEY) ON COMMIT DROP;
    INSERT INTO "SelectedHawalas" SELECT * FROM jsonb_to_recordset(coalesce(p->'HawalaIds','[]'::jsonb)) AS x("Id" bigint);
    CREATE TEMP TABLE "SettlementBalances"("RowId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"HawalaId" bigint,"HawalaNumber" bigint,"SourceCurrencyId" bigint NOT NULL,"SourceCurrencyCode" text NOT NULL,"SourcePriority" integer NOT NULL,
        "SourceTalabKar" numeric(18,4) NOT NULL,"SourceBadehKar" numeric(18,4) NOT NULL,"ExchangeRate" numeric(18,8) NOT NULL,"TargetTalabKar" numeric(18,4) NOT NULL DEFAULT 0,"TargetBadehKar" numeric(18,4) NOT NULL DEFAULT 0) ON COMMIT DROP;
    IF mode='Hawalas' THEN
        IF NOT EXISTS(SELECT 1 FROM "SelectedHawalas") THEN RAISE EXCEPTION 'حداقل یک حواله را برای تبدیل انتخاب کنید.'; END IF;
        PERFORM 1 FROM public."Hawalas" h JOIN "SelectedHawalas" s ON s."Id"=h."Id" WHERE h."TenantId"=tenant FOR UPDATE OF h;
        IF EXISTS(SELECT 1 FROM "SelectedHawalas" s LEFT JOIN public."Hawalas" h ON h."TenantId"=tenant AND h."Id"=s."Id" AND h."CorrespondentId"=owner AND h."Status"<>'Cancel'
            AND CASE WHEN h."HawalaType"='HawalaSend' THEN h."ToCurrencyId" ELSE h."FromCurrencyId" END<>target WHERE h."Id" IS NULL OR EXISTS(SELECT 1 FROM public."CorrespondentSettlementConversionHawalas" l WHERE l."TenantId"=tenant AND l."HawalaId"=s."Id")) THEN RAISE EXCEPTION 'یک یا چند حواله معتبر نیست، قبلاً تبدیل شده یا به ارز توافقی ثبت شده است.'; END IF;
        INSERT INTO "SettlementBalances"("HawalaId","HawalaNumber","SourceCurrencyId","SourceCurrencyCode","SourcePriority","SourceTalabKar","SourceBadehKar","ExchangeRate")
        SELECT h."Id",h."Number",e."CurrencyId",c."Code",c."QuotationPriority",greatest(sum(e."TalabKar")-sum(e."BadehKar"),0)::numeric(18,4),greatest(sum(e."BadehKar")-sum(e."TalabKar"),0)::numeric(18,4),coalesce(r."Rate",0)
        FROM "SelectedHawalas" s JOIN public."Hawalas" h ON h."TenantId"=tenant AND h."Id"=s."Id" JOIN public."LedgerEntries" e ON e."TenantId"=tenant AND e."HawalaId"=h."Id" AND e."AccountId"=account AND e."CurrencyId"<>target
        JOIN public."Currencies" c ON c."TenantId"=tenant AND c."Id"=e."CurrencyId" LEFT JOIN "SettlementRates" r ON r."HawalaId"=h."Id" AND r."SourceCurrencyId"=e."CurrencyId"
        GROUP BY h."Id",h."Number",e."CurrencyId",c."Code",c."QuotationPriority",r."Rate" HAVING sum(e."TalabKar")<>sum(e."BadehKar");
        IF(SELECT count(DISTINCT "HawalaId") FROM "SettlementBalances")<>(SELECT count(*) FROM "SelectedHawalas") OR EXISTS(SELECT 1 FROM "SettlementBalances" WHERE "ExchangeRate"<=0) THEN RAISE EXCEPTION 'مانده قابل تبدیل یا نرخ یک یا چند حواله معتبر نیست.'; END IF;
    ELSE
        IF NOT EXISTS(SELECT 1 FROM "SettlementRates" WHERE "HawalaId"=0 AND "Rate">0) THEN RAISE EXCEPTION 'حداقل یک ارز را برای تبدیل انتخاب کنید.'; END IF;
        INSERT INTO "SettlementBalances"("SourceCurrencyId","SourceCurrencyCode","SourcePriority","SourceTalabKar","SourceBadehKar","ExchangeRate")
        SELECT b."CurrencyId",c."Code",c."QuotationPriority",greatest(b."Balance",0)::numeric(18,4),greatest(-b."Balance",0)::numeric(18,4),r."Rate"
            FROM public.ufn_accountoperationalbalances_v1(tenant,account,NULL) b JOIN public."Currencies" c ON c."TenantId"=tenant AND c."Id"=b."CurrencyId"
            JOIN "SettlementRates" r ON r."SourceCurrencyId"=b."CurrencyId" AND r."HawalaId"=0 AND r."Rate">0 WHERE b."CurrencyId"<>target AND b."Balance"<>0;
        IF(SELECT count(*) FROM "SettlementBalances")<>(SELECT count(*) FROM "SettlementRates" WHERE "HawalaId"=0 AND "Rate">0) THEN RAISE EXCEPTION 'یک یا چند ارز انتخاب‌شده دیگر مانده قابل تبدیل ندارد.'; END IF;
    END IF;
    UPDATE "SettlementBalances" SET "TargetTalabKar"=CASE WHEN "SourceTalabKar">"SourceBadehKar" THEN round(CASE WHEN "SourcePriority"<target_priority OR("SourcePriority"=target_priority AND "SourceCurrencyCode"<target_code)
        THEN("SourceTalabKar"-"SourceBadehKar")*"ExchangeRate" ELSE("SourceTalabKar"-"SourceBadehKar")/"ExchangeRate" END,greatest(0,least(8,places)))::numeric(18,4) ELSE 0 END,
        "TargetBadehKar"=CASE WHEN "SourceBadehKar">"SourceTalabKar" THEN round(CASE WHEN "SourcePriority"<target_priority OR("SourcePriority"=target_priority AND "SourceCurrencyCode"<target_code)
        THEN("SourceBadehKar"-"SourceTalabKar")*"ExchangeRate" ELSE("SourceBadehKar"-"SourceTalabKar")/"ExchangeRate" END,greatest(0,least(8,places)))::numeric(18,4) ELSE 0 END;
    IF EXISTS(SELECT 1 FROM "SettlementBalances" WHERE "TargetTalabKar"<=0 AND "TargetBadehKar"<=0) THEN RAISE EXCEPTION 'حاصل یک یا چند تبدیل معتبر نیست.'; END IF;
    clearing:=hawala.system_account(tenant,'SYS-SETTLEMENT-CLEARING','حساب واسط تبدیل ارز نمایندگی‌ها','CurrencyConversionClearing');
    SELECT "Id" INTO branch FROM public."Branches" WHERE "TenantId"=tenant ORDER BY("Code"='HQ') DESC,"Id" LIMIT 1;
    IF NOT FOUND THEN RAISE EXCEPTION 'برای صرافی جاری هیچ شعبه‌ای تعریف نشده است.'; END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('SettlementConversionNumber:'||tenant,0));prefix:='SC-'||to_char(now_utc,'YYYYMMDD')||'-';
    SELECT coalesce(max(CASE WHEN suffix COLLATE "C" ~ '^[0-9]{1,10}$' THEN CASE WHEN suffix::numeric<=2147483646 THEN suffix::integer END END),0)+1 INTO next_number
        FROM(SELECT substring("TransactionNo",length(prefix)+1) AS suffix FROM public."Transactions" WHERE "TenantId"=tenant AND left("TransactionNo",length(prefix))=prefix)n;
    INSERT INTO public."Transactions"("TenantId","TransactionNo","TransactionType","BranchId","Status","Remarks","CreatedBy","CreatedAt") VALUES
        (tenant,prefix||lpad(next_number::text,greatest(4,length(next_number::text)),'0'),'CorrespondentSettlementConversion',branch,'Paid',
        CASE WHEN mode='Hawalas' THEN 'تبدیل حواله‌های نمایندگی ' ELSE 'تبدیل حساب نمایندگی ' END||owner_name||' به '||target_code||coalesce('. '||note,''),actor,now_utc) RETURNING "Id" INTO posting;
    INSERT INTO public."CorrespondentSettlementConversions"("TenantId","CorrespondentId","TargetCurrencyId","TransactionId","SourceMode","Note","CreatedAt","CreatedBy")
        VALUES(tenant,owner,target,posting,mode,note,now_utc,actor) RETURNING "Id" INTO conversion;
    IF mode='Hawalas' THEN
        INSERT INTO public."CorrespondentSettlementConversionHawalas"("TenantId","ConversionId","HawalaId") SELECT tenant,conversion,"Id" FROM "SelectedHawalas";
        GET DIAGNOSTICS hawala_count=ROW_COUNT;
        INSERT INTO public."CorrespondentSettlementConversionHawalaItems"("TenantId","ConversionId","HawalaId","SourceCurrencyId","SourceTalabKar","SourceBadehKar","ExchangeRate","TargetTalabKar","TargetBadehKar")
            SELECT tenant,conversion,"HawalaId","SourceCurrencyId","SourceTalabKar","SourceBadehKar","ExchangeRate","TargetTalabKar","TargetBadehKar" FROM "SettlementBalances";
    ELSE
        INSERT INTO public."CorrespondentSettlementConversionHawalas"("TenantId","ConversionId","HawalaId") SELECT tenant,conversion,h."Id" FROM public."Hawalas" h
            WHERE h."TenantId"=tenant AND h."CorrespondentId"=owner AND h."Status"<>'Cancel' AND CASE WHEN h."HawalaType"='HawalaSend' THEN h."ToCurrencyId" ELSE h."FromCurrencyId" END IN(SELECT "SourceCurrencyId" FROM "SettlementBalances")
            AND NOT EXISTS(SELECT 1 FROM public."CorrespondentSettlementConversionHawalas" l WHERE l."TenantId"=tenant AND l."HawalaId"=h."Id");
        GET DIAGNOSTICS hawala_count=ROW_COUNT;
        INSERT INTO public."CorrespondentSettlementConversionItems"("TenantId","ConversionId","SourceCurrencyId","SourceTalabKar","SourceBadehKar","ExchangeRate","TargetTalabKar","TargetBadehKar")
            SELECT tenant,conversion,"SourceCurrencyId","SourceTalabKar","SourceBadehKar","ExchangeRate","TargetTalabKar","TargetBadehKar" FROM "SettlementBalances";
    END IF;
    description:='تبدیل مانده نمایندگی '||owner_name||' به ارز توافقی';
    INSERT INTO public."LedgerEntries"("TenantId","TransactionId","AccountId","CurrencyId","TalabKar","BadehKar","SettlementHawalaItemId","Description","CreatedAt")
        SELECT tenant,posting,e.account_id,e.currency_id,e.credit,e.debit,i."Id",description,now_utc FROM "SettlementBalances" b
        LEFT JOIN public."CorrespondentSettlementConversionHawalaItems" i ON i."TenantId"=tenant AND i."ConversionId"=conversion AND i."HawalaId"=b."HawalaId" AND i."SourceCurrencyId"=b."SourceCurrencyId"
        CROSS JOIN LATERAL(VALUES(account,b."SourceCurrencyId",b."SourceBadehKar",b."SourceTalabKar"),(clearing,b."SourceCurrencyId",b."SourceTalabKar",b."SourceBadehKar"),
            (account,target,b."TargetTalabKar",b."TargetBadehKar"),(clearing,target,b."TargetBadehKar",b."TargetTalabKar"))e(account_id,currency_id,credit,debit);
    SELECT count(DISTINCT "SourceCurrencyId")::integer INTO currency_count FROM "SettlementBalances";
    INSERT INTO public."AuditLogs"("TenantId","UserId","ProcessId","Action","TableName","RecordId","NewValue","CreatedAt") VALUES
        (tenant,actor,gen_random_uuid(),CASE WHEN mode='Hawalas' THEN 'CONVERT_HAWALAS_TO_SETTLEMENT' ELSE 'CONVERT_BALANCE_TO_SETTLEMENT' END,'CorrespondentSettlementConversions',conversion,
        'نمایندگی '||owner_name||': '||currency_count||' ارز و '||hawala_count||' حواله به '||target_code||' تبدیل شد.',now_utc);
    SELECT json_build_array((SELECT json_agg(q) FROM(SELECT conversion AS "ConversionId",posting AS "TransactionId",hawala_count AS "HawalaCount",currency_count AS "CurrencyCount")q),
        (SELECT json_agg(q) FROM(SELECT "HawalaId","HawalaNumber","SourceCurrencyCode",abs("SourceTalabKar"-"SourceBadehKar")::numeric(18,4) AS "SourceAmount",
            CASE WHEN "SourceTalabKar">"SourceBadehKar" THEN 'طلبکار' ELSE 'بدهکار' END AS "BalanceDirection","ExchangeRate",target_code AS "TargetCurrencyCode",abs("TargetTalabKar"-"TargetBadehKar")::numeric(18,4) AS "TargetAmount"
            FROM "SettlementBalances" ORDER BY "HawalaNumber","SourceCurrencyCode")q)) INTO result;
    PERFORM set_config('lock_timeout',previous_timeout,true);RETURN result;
END $body$;
